def seg(a,b,c="#1d2a6b",w=3,dash=0): return {"p":[*Q2[a],*Q2[b]],"c":c,"w":w,"dash":dash}
def F(st):
  g={"type":"plot","axes":False,"X":[-9,16],"Y":[-6,14],"eq":True,"w":600,"h":420,"pad":26,
     "segs":[seg("A","B",dash=1),seg("A","D",dash=1),seg("A","S",dash=1),seg("S","B"),seg("S","C"),seg("S","D"),seg("D","C"),seg("C","B")],"pts":[]}
  T={"A":"A(0,0,0)","B":"B(0,12,0)","C":"C(12,12,0)","D":"D(12,0,0)","S":"S(0,0,12)","E":"E(9,0,3)","N":"N(6,6,6)"}
  L={"A":(8,-12),"B":(10,6),"C":(8,26),"D":(-40,26),"S":(-30,-14),"E":(-96,6),"N":(10,-8)}
  names="ABCDS"+("EN" if st>=2 else "")
  for k in names:
    x,y=Q2[k]; t=T[k] if st>=1 or k in "AB" else k
    if st<1 and k in "AB": t=T[k] if st>=1 else k
    g["pts"].append({"x":x,"y":y,"t":t,"r":6,"c":"#c8242f" if k in "EN" else "#1d2a6b","dx":L[k][0],"dy":L[k][1],"fs":19})
  if st>=3: g["poly"]=[{"p":[Q2["E"],Q2["N"],Q2["B"]],"fill":"#f5b83d","op":.45}]
  if st>=4: g["segs"]+= [seg("S","N","#16824f",4),seg("N","C","#2f55c8",4)]
  return g
